/* ── helpers ── */
function pmt(pv, i, n) {
  if (i === 0) return pv / n;
  return (pv * (i * Math.pow(1 + i, n))) / (Math.pow(1 + i, n) - 1);
}
const fmt = (v) => v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

