function CookieBanner() {
  const [visible, setVisible] = useState(() => {
    try { return !localStorage.getItem("qf_cookies_accepted"); }
    catch { return true; }
  });
  const [showDetails, setShowDetails] = useState(false);

  const accept = (all) => {
    try { localStorage.setItem("qf_cookies_accepted", all ? "all" : "essential"); }
    catch {}
    setVisible(false);
  };

  if (!visible) return null;

  return (
    <div style={{
      position: "fixed", bottom: 0, left: 0, right: 0, zIndex: 999,
      background: "linear-gradient(135deg,#0d1120ee,#0f1428ee)",
      backdropFilter: "blur(16px)",
      borderTop: "1.5px solid #1e2840",
      padding: "16px clamp(12px,4vw,40px)",
      boxShadow: "0 -8px 40px rgba(0,0,0,0.5)",
    }}>
      <div style={{ maxWidth: 1000, margin: "0 auto", display: "flex", alignItems: "flex-start", gap: 20, flexWrap: "wrap" }}>
        <div style={{ flex: 1, minWidth: 260 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <span style={{ fontSize: "1.1rem" }}>🍪</span>
            <span style={{ fontWeight: 700, fontSize: "0.82rem", color: "#e2e8ff", fontFamily: "'Sora',sans-serif" }}>Usamos cookies</span>
          </div>
          <p style={{ fontSize: "0.72rem", color: "#7a8ab0", lineHeight: 1.6, margin: 0 }}>
            Utilizamos cookies essenciais para o funcionamento do site e cookies analíticos para melhorar sua experiência. Nenhum dado é vendido a terceiros.{" "}
            <button onClick={() => setShowDetails(v => !v)} style={{ background: "none", border: "none", color: "#4a7cff", cursor: "pointer", fontSize: "0.72rem", padding: 0, textDecoration: "underline" }}>
              {showDetails ? "Ocultar detalhes" : "Saiba mais"}
            </button>
          </p>
          {showDetails && (
            <div style={{ marginTop: 10, display: "flex", flexDirection: "column", gap: 6 }}>
              {[
                ["🔒 Essenciais", "Necessários para o funcionamento básico. Sempre ativos.", true],
                ["📊 Analíticos", "Google Analytics — visitas anônimas para melhorar o site.", false],
                ["📢 Publicidade", "Google AdSense — anúncios relevantes baseados no contexto.", false],
              ].map(([nome, desc, always]) => (
                <div key={nome} style={{ display: "flex", alignItems: "flex-start", gap: 8, background: "#080c17", borderRadius: 8, padding: "8px 12px", border: "1px solid #1e2840" }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: "0.7rem", fontWeight: 700, color: "#c8d4f0" }}>{nome}</div>
                    <div style={{ fontSize: "0.62rem", color: "#5a6a9a", marginTop: 2 }}>{desc}</div>
                  </div>
                  <div style={{ fontSize: "0.6rem", color: always ? "#4ade80" : "#4a5880", fontFamily: "'DM Mono',monospace", flexShrink: 0, marginTop: 2 }}>
                    {always ? "SEMPRE ATIVO" : "OPCIONAL"}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
        <div style={{ display: "flex", gap: 10, alignItems: "center", flexShrink: 0, flexWrap: "wrap" }}>
          <button onClick={() => accept(false)} style={{ background: "transparent", border: "1.5px solid #2a3860", color: "#8899cc", borderRadius: 8, padding: "9px 18px", fontSize: "0.75rem", fontWeight: 600, cursor: "pointer", fontFamily: "'Sora',sans-serif", whiteSpace: "nowrap" }}>
            Só essenciais
          </button>
          <button onClick={() => accept(true)} style={{ background: "linear-gradient(135deg,#4a7cff,#7b4fff)", border: "none", color: "#fff", borderRadius: 8, padding: "9px 22px", fontSize: "0.75rem", fontWeight: 700, cursor: "pointer", fontFamily: "'Sora',sans-serif", whiteSpace: "nowrap", boxShadow: "0 4px 16px #4a7cff44" }}>
            Aceitar todos
          </button>
        </div>
      </div>
    </div>
  );
}

function SectionTitle({ icon, title }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
      <span style={{ fontSize: "1.3rem" }}>{icon}</span>
      <h2 style={{ fontSize: "clamp(1rem,2.5vw,1.25rem)", fontWeight: 800, color: "#fff", letterSpacing: "-0.03em" }}>{title}</h2>
      <div style={{ flex: 1, height: 1, background: "linear-gradient(90deg,#1e2840,transparent)" }} />
    </div>
  );
}

function FAQ({ q, a }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ background: "linear-gradient(135deg,#0d1120,#0f1428)", border: `1.5px solid ${open ? "#2a3860" : "#1a2035"}`, borderRadius: 12, overflow: "hidden" }}>
      <button onClick={() => setOpen(!open)} style={{ width: "100%", padding: "14px 16px", background: "transparent", border: "none", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}>
        <span style={{ fontSize: "0.83rem", fontWeight: 600, color: "#c8d4f0", textAlign: "left" }}>{q}</span>
        <span style={{ color: "#4a7cff", fontSize: "1.1rem", flexShrink: 0, transition: "transform 0.2s", transform: open ? "rotate(45deg)" : "none" }}>+</span>
      </button>
      {open && (
        <div style={{ padding: "0 16px 14px", fontSize: "0.8rem", color: "#7a8ab0", lineHeight: 1.7, borderTop: "1px solid #1a2035" }}>
          <div style={{ paddingTop: 10 }}>{a}</div>
        </div>
      )}
    </div>
  );
}
